  <style>
    *, *::before, *::after { box-sizing:border-box; margin:0; padding:0; }
    :root { --violet:#7c3aed; --violet-mid:#9d4edd; --text:#1a1a2e; --muted:#6b7280; --line:#e5e7eb; --surface:#f9fafb; }
    html, body { min-height:100%; font-family:'Inter', system-ui, sans-serif; background: radial-gradient(circle at top left, rgba(245, 158, 11, 0.16), transparent 24%), radial-gradient(circle at 85% 16%, rgba(216, 180, 254, 0.62), transparent 23%), linear-gradient(160deg, #dccdea 0%, #f8f3fe 54%, #e2e5f4 100%); color: var(--text); }
    .recovery-page{min-height:100vh;display:grid;place-items:center;padding:2rem;background:linear-gradient(180deg, rgba(210, 196, 229, 0.95) 0%, rgba(190, 172, 216, 0.72) 52%, rgba(156, 140, 186, 0.42) 100%)} .recovery-card{width:min(100%,980px);display:grid;grid-template-columns:1.05fr 0.95fr;background:#fff;border-radius:28px;overflow:hidden;box-shadow:0 28px 70px rgba(51,24,96,.22)} .recovery-brand-panel{padding:3rem;background:radial-gradient(circle at top left, rgba(216,180,254,.8), transparent 38%), linear-gradient(145deg,#581c87 0%,#7c3aed 55%,#c084fc 100%);display:flex;flex-direction:column;justify-content:center;gap:1rem} .recovery-brand-content{display:flex;flex-direction:column;gap:1rem} .recovery-brand-headline{display:inline-flex;align-items:center;gap:.58rem;font-size:clamp(1.95rem,2.8vw,2.55rem);font-weight:800;color:#fff;line-height:1.08;letter-spacing:-.05em}.recovery-brand-desc{font-size:1rem;color:rgba(255,255,255,.82);line-height:1.6;max-width:21rem}.recovery-form-panel{display:flex;flex-direction:column;justify-content:center;padding:3rem;background:#fff}.recovery-form-wrap{width:100%;max-width:400px;margin:0 auto}.recovery-form-title{font-size:1.8rem;font-weight:800;color:var(--text);letter-spacing:-.04em;margin-bottom:.4rem}.recovery-form-sub{font-size:.9rem;color:var(--muted);margin-bottom:2rem;line-height:1.6}.recovery-field label{display:block;font-size:.85rem;font-weight:600;color:var(--text);margin-bottom:.45rem}.recovery-input-wrap{position:relative}.recovery-input-wrap>i{position:absolute;left:.9rem;top:50%;transform:translateY(-50%);font-size:1.05rem;color:#9ca3af}.recovery-input{width:100%;padding:.75rem 1rem .75rem 2.5rem;border:1.5px solid var(--line);border-radius:10px;font-family:inherit;font-size:.95rem;color:var(--text);background:var(--surface);outline:none}.recovery-btn-primary{width:100%;padding:.85rem 1.5rem;border:none;border-radius:10px;background:linear-gradient(135deg,var(--violet) 0%, var(--violet-mid) 100%);color:#fff;font-family:inherit;font-size:1rem;font-weight:700;cursor:pointer;margin-top:.7rem}.recovery-back-note{margin-top:1.1rem;font-size:.9rem;color:var(--muted);text-align:center;line-height:1.55}.recovery-back-note a{color:var(--violet);font-weight:600;text-decoration:none}.recovery-alert{padding:.7rem 1rem;border-radius:8px;font-size:.85rem;font-weight:500;margin-bottom:1.1rem}.recovery-alert--error{background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.recovery-alert--success{background:#f0fdf4;color:#166534;border:1px solid #bbf7d0}@media (max-width:860px){.recovery-card{grid-template-columns:1fr}.recovery-brand-panel,.recovery-form-panel{padding:2rem}}@media (max-width:640px){.recovery-page{padding:.8rem;place-items:stretch}.recovery-card{width:100%;min-height:calc(100vh - 1.6rem);border-radius:20px;box-shadow:0 18px 40px rgba(76,29,149,.12)}.recovery-form-panel{padding:1.35rem 1.1rem 2rem}.recovery-brand-panel{padding:.9rem 1.1rem 1rem;min-height:132px}.recovery-brand-headline{font-size:1.34rem}.recovery-brand-desc{max-width:none;font-size:.84rem;line-height:1.35}}
  </style>
</head>
<body>
<main class="recovery-page"><section class="recovery-card" aria-label="{{ __('lexi.auth.forgot_aria') }}"><aside class="recovery-brand-panel"><div class="recovery-brand-content"><h1 class="recovery-brand-headline">{{ __('lexi.auth.forgot_brand_title') }} <i class="bi bi-key" aria-hidden="true"></i></h1><p class="recovery-brand-desc">{{ __('lexi.auth.forgot_brand_text') }}</p></div></aside><div class="recovery-form-panel"><div class="recovery-form-wrap"><h2 class="recovery-form-title">{{ __('lexi.auth.forgot_heading') }}</h2><p class="recovery-form-sub">{{ __('lexi.auth.forgot_subtitle') }}</p>@if ($errors->any())<div class="recovery-alert recovery-alert--error" role="alert">{{ $errors->first() }}</div>@endif @if (session('status'))<div class="recovery-alert recovery-alert--success" role="alert">{{ session('status') }}</div>@endif <form method="POST" action="{{ route('password.email') }}" novalidate>@csrf<div class="recovery-field"><label for="recoveryEmail">{{ __('lexi.auth.email') }}</label><div class="recovery-input-wrap"><i class="bi bi-envelope"></i><input type="email" id="recoveryEmail" name="email" class="recovery-input" placeholder="{{ __('lexi.auth.email_placeholder') }}" value="{{ old('email') }}" autocomplete="email" required></div></div><button type="submit" class="recovery-btn-primary">{{ __('lexi.auth.forgot_submit') }}</button></form><p class="recovery-back-note">{{ __('lexi.auth.forgot_back_prompt') }} <a href="{{ route('login') }}">{{ __('lexi.auth.sign_in_link') }}</a></p></div></div></section></main>
